import{_ as a,a as e}from"./chunks/MVP.CL4Yuaen.js";import{_ as l,o as r,c as t,a2 as o}from"./chunks/framework.DfDAiEgj.js";const m=JSON.parse('{"title":"BRD 1","description":"","frontmatter":{},"headers":[],"relativePath":"skill/BRD.md","filePath":"skill/BRD.md","lastUpdated":null}'),n={name:"skill/BRD.md"};function s(h,i,p,u,d,c){return r(),t("div",null,[...i[0]||(i[0]=[o('<h1 id="brd-1" tabindex="-1">BRD <a href="http://www.woshipm.com/pmd/178527.html" target="_blank" rel="noreferrer">1</a> <a class="header-anchor" href="#brd-1" aria-label="Permalink to &quot;BRD [1]&quot;">​</a></h1><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>BRD指的是商业需求文档（Business Requirement Document）。在这篇的文档当中不会有详细的产品规划，只会有基于市场调查和用户需求调查的产品构思。</p><p>BRD 是给谁看的呢？老板、投资人、股东，目的是让他们知道这款产品如何给公司盈利。BRD 的撰写侧重点是需求描述、盈利模式。产品总监或者产品VP（Vice President，副总监）才需要写BRD，初级产品经理基本接触不到BRD</p><p>这篇文档常以PPT等形式，以数据说服他们，帮产品的立项，来获得公司资源支持。</p><h2 id="顺势而为-7" tabindex="-1">顺势而为 <a href="https://www.jianshu.com/p/a4b1fd94b49a" target="_blank" rel="noreferrer">7</a> <a class="header-anchor" href="#顺势而为-7" aria-label="Permalink to &quot;顺势而为 [7]&quot;">​</a></h2><p><img src="'+a+'" alt="点子过滤"></p><h2 id="产品立项流程-4" tabindex="-1">产品立项流程 <a href="https://www.bilibili.com/video/BV1254y1D7Ht?from=search&amp;seid=14167562900175777805" target="_blank" rel="noreferrer">4</a> <a class="header-anchor" href="#产品立项流程-4" aria-label="Permalink to &quot;产品立项流程 [4]&quot;">​</a></h2><p>项目概述 商业价值 项目的目标 项目风险 项目干系人、组织和其他产品</p><h2 id="前期调研-3" tabindex="-1">前期调研 <a href="https://www.bilibili.com/video/BV1wz4y1y7sg" target="_blank" rel="noreferrer">3</a> <a class="header-anchor" href="#前期调研-3" aria-label="Permalink to &quot;前期调研 [3]&quot;">​</a></h2><p>人群特征 需求特点 用户价值 体量规模 竞争优势 产品定位 资源能力 成本收益</p><h2 id="产品目的-2" tabindex="-1">产品目的 <a href="http://www.woshipm.com/pmd/21446.html" target="_blank" rel="noreferrer">2</a> <a class="header-anchor" href="#产品目的-2" aria-label="Permalink to &quot;产品目的 [2]&quot;">​</a></h2><p>提出一个清晰、简明的价值主张，让它很容易被接受，要让产品团队、管理人员、用户、市场人员清楚的明白这个产品到底是什么意图。</p><p>考虑“velevator pitch ”(电梯间演讲、电梯行销)测试。</p><h2 id="一个中心" tabindex="-1">一个中心 <a class="header-anchor" href="#一个中心" aria-label="Permalink to &quot;一个中心&quot;">​</a></h2><p>收益！来生存</p><h2 id="多个基本点" tabindex="-1">多个基本点 <a class="header-anchor" href="#多个基本点" aria-label="Permalink to &quot;多个基本点&quot;">​</a></h2><ol><li>市场调查报告；</li><li>竞争对手报告；</li><li>用户需求调研报告；</li><li>产品功能构思；</li><li>产品运营构思；</li><li>收益分析；</li><li>风险分析；</li><li>其他。</li></ol><h2 id="可行性评估-3" tabindex="-1">可行性评估 <a href="https://www.bilibili.com/video/BV1wz4y1y7sg" target="_blank" rel="noreferrer">3</a> <a class="header-anchor" href="#可行性评估-3" aria-label="Permalink to &quot;可行性评估 [3]&quot;">​</a></h2><p>MVP:核心是试错，有反馈渠道。 PMF:Dropbox用视频介绍产品的功能，来测试反馈。核心功能内测</p><p>最短时间 最小成本 可行性验证</p><h2 id="可用性测试" tabindex="-1">可用性测试 <a class="header-anchor" href="#可用性测试" aria-label="Permalink to &quot;可用性测试&quot;">​</a></h2><h3 id="确定测试目标" tabindex="-1">确定测试目标: <a class="header-anchor" href="#确定测试目标" aria-label="Permalink to &quot;确定测试目标:&quot;">​</a></h3><ul><li>产品设计方案</li><li>测试功能点</li><li>A/B测试</li><li>产品改进方案测试</li></ul><h3 id="定义用户" tabindex="-1">定义用户: <a class="header-anchor" href="#定义用户" aria-label="Permalink to &quot;定义用户:&quot;">​</a></h3><ul><li>可从用户访谈和问卷调查中选择</li><li>存量用户或者新用户</li></ul><h3 id="测试过程记录" tabindex="-1">测试过程记录: <a class="header-anchor" href="#测试过程记录" aria-label="Permalink to &quot;测试过程记录:&quot;">​</a></h3><ul><li>录屏、录音和摄像</li><li>记录A/B选项结果</li><li>页面埋点追踪</li><li>过程中的疑惑点,改进点及时其他特殊情况</li></ul><h3 id="结果分析根据过程记录总结、修改方案-如" tabindex="-1">结果分析根据过程记录总结、修改方案,如: <a class="header-anchor" href="#结果分析根据过程记录总结、修改方案-如" aria-label="Permalink to &quot;结果分析根据过程记录总结、修改方案,如:&quot;">​</a></h3><ul><li>通过统计分析追踪结果</li><li>AB测试结果得出改进方案</li></ul><h2 id="四轮-mvp-框架" tabindex="-1">四轮 MVP 框架 <a class="header-anchor" href="#四轮-mvp-框架" aria-label="Permalink to &quot;四轮 MVP 框架&quot;">​</a></h2><p>VUCA 的中文含义分别对应着易变性、不确定性、复杂性和模糊性。V：Volatility 易变性U：Uncertainty 不确定性C：Complexity 复杂性A：Ambiguity 模糊性</p><p>如今VUCA时代信息无时无刻不在变化，用户的需求无时无刻不在变化。</p><p><img src="'+e+'" alt="MVP框架"></p><ol><li>Paperwork：产出物是纸面研究的结论，用的方法是 Discovery Sprint，探索冲刺。</li><li>Prototype：在方案层面“先发散，后收敛”，做出原型，获得反馈后，不断修正原型，用的方法叫 Design Sprint，设计冲刺。</li><li>Product：验证的重点是真实产品是否可以培养出用户习惯，用户愿意用，能更高效地解决用户需求、创造价值，并且让用户愿意反复使用。这时候，我们会关注某些和用户留存有关的指标。</li><li>Promotion：做小规模推广尝试，测试渠道，逐步确定优选渠道，降低分销成本。对应的方法论是 Distribution Sprint，分销冲刺。</li></ol><p>注意：</p><ol><li>用户参与都是必须的</li><li>过滤器的开口应该越来越小</li><li>在每一轮停留的时间、投入的资源也不尽相同</li><li>这四轮走完，产品也才刚刚上路</li></ol><h2 id="项目风险-raid-4" tabindex="-1">项目风险 RAID <a href="https://www.bilibili.com/video/BV1254y1D7Ht?from=search&amp;seid=14167562900175777805" target="_blank" rel="noreferrer">4</a> <a class="header-anchor" href="#项目风险-raid-4" aria-label="Permalink to &quot;项目风险 RAID [4]&quot;">​</a></h2><ul><li>Risk风险：会对项目产生负面影响的事件,事件可能发生的概率和随之对项目带来的影响</li><li>Assumption假设：知群可以预想到的因素,一旦发生就会促进项目成功(但不发生就没有促进效果)</li><li>Issues问题：在项目中任何不怡当的,需要管理和解决的事情,这些事情需要持续跟踪并记录</li><li>Dependence依赖：任何项目所依赖的或者依赖该项目的事件和工作,需要记录依赖实现的时间</li></ul><h2 id="pest分析-5" tabindex="-1">PEST分析 <a href="https://zh.wikipedia.org/wiki/PEST%E5%88%86%E6%9E%90" target="_blank" rel="noreferrer">5</a> <a class="header-anchor" href="#pest分析-5" aria-label="Permalink to &quot;PEST分析 [5]&quot;">​</a></h2><p>政治因素包含了租税政策、劳工法律、环境管制、贸易限制、关税与政治稳定。 经济因素有经济增长、利率、汇率和通货膨胀率。 社会因素通常着重在文化观点，另外还有健康意识、人口成长率、年龄结构、工作态度及安全需求。 科技因素包含生态与环境方面，决定进入障碍和最低有效生产水准，影响委外购买决策。科技因素着重在研发活动、自动化、技术诱因和科技发展的速度。</p><p>PEST分析与外部总体环境的因素互相结合就可归纳出SWOT分析中的机会与威胁。</p><h2 id="波特五力分析-6" tabindex="-1">波特五力分析 <a href="https://zh.wikipedia.org/wiki/PEST%E5%88%86%E6%9E%90" target="_blank" rel="noreferrer">6</a> <a class="header-anchor" href="#波特五力分析-6" aria-label="Permalink to &quot;波特五力分析 [6]&quot;">​</a></h2><p>波特五力分析来定义出一个市场吸引力高低程度。</p><p>来自买方的议价能力、来自供应商的议价能力、来自潜在进入者的威胁、来自替代品的威胁和潜在竞争者的威胁 — 共同组合而演变出影响公司的第五种力量：来自现有竞争者的威胁。而每一种力量都由数项指标决定：</p><ol><li>来自买方的议价能力（Bargaining power of customers）</li><li>来自供应商的议价能力（Bargaining power of suppliers）</li><li>来自潜在进入者的威胁（Threat of new entrants）</li><li>来自替代品的威胁（Threat of substitutes）</li><li>来自现有竞争者的威胁（Competitive rivalry）</li></ol><h3 id="来自买方的议价能力-bargaining-power-of-customers" tabindex="-1">来自买方的议价能力（Bargaining power of customers） <a class="header-anchor" href="#来自买方的议价能力-bargaining-power-of-customers" aria-label="Permalink to &quot;来自买方的议价能力（Bargaining power of customers）&quot;">​</a></h3><ul><li>买方集中度（buyer concentration to firm concentration ratio）</li><li>谈判杠杆（bargaining leverage）</li><li>买方购买数量（total buyer volume）</li><li>买方相对于厂商的转换成本（buyer switching costs relative to firm switching costs）</li><li>买方获取资讯的能力（buyer information availability）</li><li>买方垂直整合（bargaining leverage，backward vertical integration）的程度或可能性</li><li>现存替代品（availability of existing substitute products or services）</li><li>消费者价格敏感度（buyer price sensitivity）</li><li>总消费金额（price of total purchase）</li></ul><h3 id="来自供应商的议价能力-bargaining-power-of-suppliers" tabindex="-1">来自供应商的议价能力（Bargaining power of suppliers） <a class="header-anchor" href="#来自供应商的议价能力-bargaining-power-of-suppliers" aria-label="Permalink to &quot;来自供应商的议价能力（Bargaining power of suppliers）&quot;">​</a></h3><ul><li>供应商相对于厂商的转换成本 （switching costs of firms in the industry）</li><li>投入原料的差异化程度</li><li>现存的替代原料（presence of substitute inputs）</li><li>供应商集中度 （supplier concentration）</li><li>供应商垂直整合（bargaining leverage，forward vertical integration）的程度或可能性</li><li>原料价格占产品售价的比例</li></ul><h3 id="来自潜在进入者的威胁-threat-of-new-entrants" tabindex="-1">来自潜在进入者的威胁（Threat of new entrants） <a class="header-anchor" href="#来自潜在进入者的威胁-threat-of-new-entrants" aria-label="Permalink to &quot;来自潜在进入者的威胁（Threat of new entrants）&quot;">​</a></h3><ul><li>消费者对替代品的偏好倾向</li><li>替代品相对的价格效用比</li><li>消费者的转换成本</li><li>消费者认知的品牌差异</li></ul><h3 id="来自现有竞争者的威胁-competitive-rivalry" tabindex="-1">来自现有竞争者的威胁（Competitive rivalry） <a class="header-anchor" href="#来自现有竞争者的威胁-competitive-rivalry" aria-label="Permalink to &quot;来自现有竞争者的威胁（Competitive rivalry）&quot;">​</a></h3><ul><li>现有竞争者的数目</li><li>产业成长率（industry growth）</li><li>产业存在超额产能的情况</li><li>退出障碍 （exit barrier）</li><li>竞争者的多样性 （diversity of rivals）</li><li>资讯的复杂度和不对称</li><li>品牌权益 （brand equity）</li><li>每单位附加价值摊提到的固定资产</li><li>大量的广告需求</li><li>不同的产品 （product differences）</li></ul>',54)])])}const g=l(n,[["render",s]]);export{m as __pageData,g as default};
